fields.InputDefinition:
{
  "goal": "Open the application switcher dropdown next to the logo and switch to the 'Scheduling' application, then open its 'Activity' left-nav section. This shared setup is done ONCE. Then exercise these controls IN ORDER, and as you finish each set \"checkpointReached\" to the exact checkpoint name shown: (1) activity-history — confirm the 'Execution History' table renders (Status, Job Name, Started, Duration, Error columns) typically with job-type summary cards and an 'Execution Trends' bar chart above it, then click an execution ROW to EXPAND it and confirm an inline detail area opens showing fields like Started/Completed/Duration/Status and 'Open Run Record' / 'Open Job' buttons (the 'No executions found' empty state is an acceptable pass when there are no rows); (2) time-range-chips — locate the time-range chips ('24 Hours', '7 Days', '30 Days', '90 Days'; 7 Days active by default), click a different range chip (e.g. '30 Days') and confirm it becomes the active/selected chip and the activity view reloads for that window (executions list and/or trends chart refresh; an empty state is acceptable). Keep going until both controls have been exercised. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "activity-history",
      "instruction": "execution history table + expandable row detail",
      "visualCriteria": [
        "The Activity section renders an Execution History table (and/or trends chart / job-type summary cards), and clicking an execution row expands an inline detail panel with Started/Completed/Status fields and Open Run Record / Open Job buttons — OR a valid 'No executions found' empty-state"
      ]
    },
    {
      "name": "time-range-chips",
      "instruction": "time-range chip changes active window",
      "visualCriteria": [
        "Time-range chips (24 Hours / 7 Days / 30 Days / 90 Days) are visible with one active, and clicking a different range makes it the active chip and the activity content refreshes for that window (rows/trends update or a valid empty-state)"
      ]
    }
  ]
}
